import { open } from "node:fs/promises"
import path from "node:path"

import { globToRegex } from "./hooks"

/**
 * Generated and vendored paths, as init offers them for the `generated-code` and `vendored-code`
 * catalog rules (plan 24). The one place that decides what counts as either.
 */

/** A path init offers for `--generated` or `--vendored`. */
export interface OfferedPath {
  /** Relative to the project; dirs end with "/". This string is what --generated / --vendored take. */
  path: string
  kind: "dir" | "file"
  files: number
  /** "header: auto-generated by @hey-api/openapi-ts", ".gitattributes linguist-generated", "vendor/ dir". */
  evidence: string
}

/** A vendored directory: someone else's code, copied in. */
export const VENDORED_DIR = /(^|\/)(vendor|third_party)\//

/** The markers generators write at the top of what they produce. */
export const GENERATED_HEADER = /@generated|DO NOT EDIT|auto-?generated|automatically generated|Code generated/i

/** How much of a file is read for its header, and how many of its lines are looked at. */
const HEAD_BYTES = 1024
const HEAD_LINES = 5
/** Marked files outside an offered dir are offered one by one, up to this many. */
const MAX_FILES = 20
const EVIDENCE_LENGTH = 80
/** Header reads in flight at once. */
const PARALLEL = 32

export interface FindInput {
  files: readonly string[]
  /** The first 1 KB of a project-relative file; null when missing or binary. */
  readHead(file: string): Promise<string | null>
  /** Reads a project-relative file; null when missing. */
  read(file: string): Promise<string | null>
  /** The catalog rule's default `files`, so already-covered paths are not offered; null when unknown. */
  covered: ((file: string) => boolean) | null
  /** The same for `vendored-code`. */
  coveredVendored?: ((file: string) => boolean) | null
}

/** The first 1 KB of `file` under `root`, or null when it is missing or holds a NUL byte (binary). */
export async function readHead(root: string, file: string): Promise<string | null> {
  let handle: Awaited<ReturnType<typeof open>> | undefined
  try {
    handle = await open(path.join(root, file), "r")
    const buffer = Buffer.alloc(HEAD_BYTES)
    const { bytesRead } = await handle.read(buffer, 0, HEAD_BYTES, 0)
    const head = buffer.subarray(0, bytesRead)
    return head.includes(0) ? null : head.toString("utf8")
  } catch {
    return null
  } finally {
    await handle?.close()
  }
}

/** The marker line of a generated file's header, or null. */
function headerLine(head: string | null): string | null {
  if (head === null) return null
  const line = head
    .split(/\r?\n/)
    .slice(0, HEAD_LINES)
    .find((candidate) => GENERATED_HEADER.test(candidate))
  return line === undefined ? null : line.trim().slice(0, EVIDENCE_LENGTH)
}

interface Attributes {
  generated: RegExp[]
  vendored: RegExp[]
}

/** A .gitattributes pattern as a regex over project paths: a name alone matches at any depth. */
function attributePattern(pattern: string): RegExp {
  const anchored = pattern.replace(/^\//, "")
  if (!pattern.replace(/\/$/, "").includes("/")) return new RegExp(`^(.*/)?${globToRegex(anchored).slice(1)}`)
  return new RegExp(globToRegex(anchored))
}

/** The `linguist-generated` and `linguist-vendored` patterns of the project's .gitattributes. */
function attributes(text: string | null): Attributes {
  const found: Attributes = { generated: [], vendored: [] }
  for (const raw of (text ?? "").split(/\r?\n/)) {
    const line = raw.trim()
    if (line === "" || line.startsWith("#")) continue
    const [pattern, ...attrs] = line.split(/\s+/)
    for (const attr of attrs) {
      if (attr === "linguist-generated" || attr === "linguist-generated=true") {
        found.generated.push(attributePattern(pattern!))
      }
      if (attr === "linguist-vendored" || attr === "linguist-vendored=true")
        found.vendored.push(attributePattern(pattern!))
    }
  }
  return found
}

/** Every dir above `file`, "/"-terminated, nearest the root first; the root itself is not one. */
function dirsOf(file: string): string[] {
  const parts = file.split("/").slice(0, -1)
  return parts.map((_, index) => `${parts.slice(0, index + 1).join("/")}/`)
}

/**
 * The topmost dirs of at least `min` files that are all marked or covered, with at least one marked;
 * then the marked files outside them, one by one. A dir or file whose files are all covered is left
 * out: the catalog default already reaches it.
 */
function group(
  files: readonly string[],
  marked: ReadonlyMap<string, string>,
  covered: (file: string) => boolean,
  min: number,
): OfferedPath[] {
  const stats = new Map<string, { total: number; ok: boolean; evidence: string | null }>()
  for (const file of files) {
    const evidence = marked.get(file) ?? null
    const ok = evidence !== null || covered(file)
    for (const dir of dirsOf(file)) {
      const entry = stats.get(dir) ?? { total: 0, ok: true, evidence: null }
      entry.total++
      entry.ok &&= ok
      entry.evidence ??= evidence
      stats.set(dir, entry)
    }
  }
  const qualifies = (dir: string) => {
    const entry = stats.get(dir)
    return entry?.ok === true && entry.total >= min && entry.evidence !== null
  }
  const offered: OfferedPath[] = []
  for (const [dir, entry] of [...stats].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
    if (!qualifies(dir) || dirsOf(dir.slice(0, -1)).some(qualifies)) continue
    offered.push({ path: dir, kind: "dir", files: entry.total, evidence: entry.evidence! })
  }
  const inDir = (file: string) => offered.some((entry) => file.startsWith(entry.path))
  const single = [...marked.keys()]
    .filter((file) => !inDir(file))
    .sort()
    .slice(0, MAX_FILES)
    .map((file): OfferedPath => ({ path: file, kind: "file", files: 1, evidence: marked.get(file)! }))
  return [...offered, ...single]
}

async function inBatches<T, R>(items: readonly T[], each: (item: T) => Promise<R>): Promise<R[]> {
  const results: R[] = []
  for (let start = 0; start < items.length; start += PARALLEL) {
    results.push(...(await Promise.all(items.slice(start, start + PARALLEL).map(each))))
  }
  return results
}

/** The project's generated and vendored paths, as init offers them. Vendored dirs are never header-scanned. */
export async function findGenerated(input: FindInput): Promise<{ generated: OfferedPath[]; vendored: OfferedPath[] }> {
  const files = input.files.filter((file) => !file.split("/").includes("node_modules"))
  const attrs = attributes(await input.read(".gitattributes"))
  const covered = input.covered ?? (() => false)
  const coveredVendored = input.coveredVendored ?? (() => false)

  // Vendored: the topmost vendor/ or third_party/ dir of each file, then linguist-vendored files grouped.
  const vendorDirs = new Map<string, { files: number; covered: boolean; name: string }>()
  const attributed = new Map<string, string>()
  const vendoredFiles = new Set<string>()
  for (const file of files) {
    const match = VENDORED_DIR.exec(file)
    if (match !== null) {
      const dir = file.slice(0, match.index + match[0].length)
      const entry = vendorDirs.get(dir) ?? { files: 0, covered: true, name: match[2]! }
      entry.files++
      entry.covered &&= coveredVendored(file)
      vendorDirs.set(dir, entry)
      vendoredFiles.add(file)
    } else if (attrs.vendored.some((pattern) => pattern.test(file))) {
      attributed.set(file, ".gitattributes linguist-vendored")
      vendoredFiles.add(file)
    }
  }
  const vendored: OfferedPath[] = [...vendorDirs]
    .filter(([, entry]) => !entry.covered)
    .map(([dir, entry]) => ({ path: dir, kind: "dir" as const, files: entry.files, evidence: `${entry.name}/ dir` }))
  vendored.push(
    ...group(
      files.filter((file) => !VENDORED_DIR.test(file)),
      new Map([...attributed].filter(([file]) => !coveredVendored(file))),
      coveredVendored,
      1,
    ),
  )
  vendored.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))

  // Generated: linguist-generated, else a generator's header. Covered files are not read.
  const candidates = files.filter((file) => !vendoredFiles.has(file) && !covered(file))
  const marked = new Map<string, string>()
  const heads = await inBatches(candidates, async (file) => {
    if (attrs.generated.some((pattern) => pattern.test(file))) return ".gitattributes linguist-generated"
    const line = headerLine(await input.readHead(file))
    return line === null ? null : `header: ${line}`
  })
  candidates.forEach((file, index) => {
    const evidence = heads[index]
    if (evidence !== null && evidence !== undefined) marked.set(file, evidence)
  })
  return { generated: group(files, marked, covered, 2), vendored }
}

const literal = (text: string) => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")

/** `defaultFiles` widened with the chosen paths, each anchored at the project: `^frontend/src/client/`, `^x/y\.ts$`. */
export function filesOverride(defaultFiles: string, paths: readonly string[]): string {
  const added = paths.map((entry) => (entry.endsWith("/") ? `^${literal(entry)}` : `^${literal(entry)}$`))
  return [defaultFiles, ...added].filter((part) => part !== "").join("|")
}
